node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const cartId = 'CART-user_1b350225';
const customerId = 'user_1b350225';
const productId = 'PROD-73FAB4';
const newItemId = 'CI-0032';
const price = 88;

// Insert the cart item
db.prepare(\`
  INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id)
  VALUES (?, ?, ?, ?, 1, 0, NULL)
\`).run(newItemId, cartId, customerId, productId);

// Update the cart: subtotal, total, and item_ids_json
db.prepare(\`
  UPDATE carts
  SET subtotal = ?,
      total = ?,
      item_ids_json = ?
  WHERE cart_id = ?
\`).run(price, price, JSON.stringify([newItemId]), cartId);

// Verify
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const items = db.prepare('SELECT * FROM cart_items WHERE cart_id = ?').all(cartId);
console.log('=== UPDATED CART ===');
console.log(JSON.stringify(cart, null, 2));
console.log('\n=== CART ITEMS ===');
console.log(JSON.stringify(items, null, 2));
"

